<?php require dirname(__DIR__).'/inc/page_helpers.php';admin_required();if(page_post()){check_csrf();$q=$db->prepare('SELECT id FROM users WHERE username=?');$q->execute([trim((string)($_POST['username']??''))]);$u=$q->fetch();$currency=(string)($_POST['currency']??'tickets');$amount=(int)($_POST['amount']??0);if($u&&in_array($currency,['tickets','robux'],true)&&$amount>0&&$amount<=1000000){$db->prepare("UPDATE users SET {$currency}={$currency}+? WHERE id=?")->execute([$amount,$u['id']]);record_currency($db,(int)$u['id'],$currency,$amount,'Administrator grant');notice('Currency granted.');}else notice('Check username, currency and amount.','error');go('/Admin/Currency.php');}page_start('Currency Tools');?><section class="Panel narrow"><h1>Grant virtual currency</h1><p>These are in-game test balances only. This page does not process payments or real money.</p><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><label>Username<input name="username" required></label><label>Currency<select name="currency"><option value="tickets">Tickets</option><option value="robux">Robux</option></select></label><label>Amount<input type="number" name="amount" min="1" max="1000000" required></label><button class="Button">Grant</button></form></section><?php page_end();?>